import React, { useState, useEffect } from 'react';
import { supabase } from './services/supabase';
import { AdminPortal }       from './components/AdminPortal';
import { AccountantPortal }  from './components/AccountantPortal';
import { VPPortal }          from './components/VPPortal';
import { CoordinatorPortal } from './components/CoordinatorPortal';
import { ExaminerPortal }    from './components/ExaminerPortal';
import { AcademicsPortal }   from './components/AcademicsPortal';
import { StudentPortal }     from './components/StudentPortal';
import { TeacherPortal }     from './components/TeacherPortal';

// ── PIC Building background ────────────────────────────────────
// PASTE YOUR EXISTING PIC_BG BASE64 VALUE HERE (from your old App.tsx)
// It starts with: "data:image/jpeg;base64,/9j/4AAQ..."
const PIC_BG = "data:image/png;base64,";

// ── Login screen ───────────────────────────────────────────────
const LoginScreen = ({ onLogin }: { onLogin: (user: any, role: string) => void }) => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading,  setLoading]  = useState(false);
  const [error,    setError]    = useState('');
  const [showPwd,  setShowPwd]  = useState(false);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!username.trim() || !password.trim()) { setError('Enter credentials'); return; }
    setLoading(true); setError('');
    try {
      // ── 1. admin_users — lowercase username ──
      const { data: a1 } = await supabase
        .from('admin_users').select('*')
        .eq('username', username.trim().toLowerCase())
        .eq('password', password.trim()).single();
      if (a1) { onLogin(a1, 'admin'); return; }

      // ── 2. admin_users — exact case ──
      const { data: a2 } = await supabase
        .from('admin_users').select('*')
        .eq('username', username.trim())
        .eq('password', password.trim()).single();
      if (a2) { onLogin(a2, 'admin'); return; }

      // ── 3. teachers — exact case ──
      const { data: t1 } = await supabase
        .from('teachers').select('*')
        .eq('username', username.trim())
        .eq('password', password.trim()).single();
      if (t1) { onLogin(t1, 'teacher'); return; }

      // ── 4. teachers — lowercase ──
      const { data: t2 } = await supabase
        .from('teachers').select('*')
        .eq('username', username.trim().toLowerCase())
        .eq('password', password.trim()).single();
      if (t2) { onLogin(t2, 'teacher'); return; }

      // ── 5. students — exact case ──
      const { data: s1 } = await supabase
        .from('students').select('*')
        .eq('username', username.trim())
        .eq('password', password.trim()).single();
      if (s1) { onLogin(s1, 'student'); return; }

      // ── 6. students — lowercase ──
      const { data: s2 } = await supabase
        .from('students').select('*')
        .eq('username', username.trim().toLowerCase())
        .eq('password', password.trim()).single();
      if (s2) { onLogin(s2, 'student'); return; }

      setError('Invalid username or password');
    } catch (err) {
      setError('Login failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const inputStyle: React.CSSProperties = {
    background: 'rgba(255,255,255,0.14)',
    border: '1px solid rgba(255,255,255,0.22)',
    color: '#fff',
    caretColor: '#fff',
  };
  const focusInput = (e: React.FocusEvent<HTMLInputElement>) => {
    e.target.style.background = 'rgba(255,255,255,0.22)';
    e.target.style.borderColor = 'rgba(255,255,255,0.45)';
  };
  const blurInput = (e: React.FocusEvent<HTMLInputElement>) => {
    e.target.style.background = 'rgba(255,255,255,0.14)';
    e.target.style.borderColor = 'rgba(255,255,255,0.22)';
  };

  return (
    <div className="min-h-screen flex items-center justify-center relative overflow-hidden"
      style={{ fontFamily: "'Segoe UI',system-ui,sans-serif" }}>

      {/* PIC Building background */}
      <div className="absolute inset-0" style={{
        backgroundImage: `url(${PIC_BG})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center top',
        backgroundRepeat: 'no-repeat',
      }}/>

      {/* Lighter overlay — keeps photo sharp */}
      <div className="absolute inset-0" style={{
        background: 'linear-gradient(160deg,rgba(0,0,0,0.30) 0%,rgba(0,0,0,0.48) 100%)',
      }}/>

      <div className="relative z-10 w-full max-w-sm px-4">

        {/* Brand */}
        <div className="text-center mb-7">
          <div className="w-20 h-20 rounded-full bg-white flex items-center justify-center mx-auto mb-4"
            style={{ boxShadow: '0 8px 40px rgba(0,0,0,0.4)' }}>
            <span className="text-xl font-black" style={{ color: '#1a2fa8' }}>PIC</span>
          </div>
          <h1 className="text-2xl font-black text-white tracking-tight">Pak Informatics</h1>
          <p className="text-sm font-bold mt-0.5" style={{ color: '#F97316' }}>Group of Colleges</p>
          <p className="text-[10px] font-black uppercase tracking-[0.25em] mt-1.5"
            style={{ color: 'rgba(255,255,255,0.4)' }}>Campus Portal</p>
        </div>

        {/* Glass card — no backdropFilter so background stays sharp */}
        <form onSubmit={handleLogin} className="rounded-3xl p-7 space-y-4" style={{
          background: 'rgba(10,20,80,0.55)',
          border: '1px solid rgba(255,255,255,0.18)',
          boxShadow: '0 20px 60px rgba(0,0,0,0.4)',
        }}>

          <div>
            <label className="block text-[10px] font-black uppercase tracking-widest mb-1.5"
              style={{ color: 'rgba(255,255,255,0.55)' }}>Username</label>
            <input value={username} onChange={e => setUsername(e.target.value)}
              placeholder="Enter your username" autoComplete="username"
              className="w-full px-4 py-3.5 rounded-2xl text-sm font-medium outline-none"
              style={inputStyle} onFocus={focusInput} onBlur={blurInput}/>
          </div>

          <div>
            <label className="block text-[10px] font-black uppercase tracking-widest mb-1.5"
              style={{ color: 'rgba(255,255,255,0.55)' }}>Password</label>
            <div className="relative">
              <input type={showPwd ? 'text' : 'password'}
                value={password} onChange={e => setPassword(e.target.value)}
                placeholder="Enter your password" autoComplete="current-password"
                className="w-full px-4 py-3.5 pr-14 rounded-2xl text-sm font-medium outline-none"
                style={inputStyle} onFocus={focusInput} onBlur={blurInput}/>
              <button type="button" onClick={() => setShowPwd(p => !p)}
                className="absolute right-4 top-1/2 -translate-y-1/2 text-[10px] font-black"
                style={{ color: 'rgba(255,255,255,0.45)' }}>
                {showPwd ? 'HIDE' : 'SHOW'}
              </button>
            </div>
          </div>

          {error && (
            <div className="flex items-center gap-2 px-4 py-3 rounded-2xl text-xs font-bold text-rose-200"
              style={{ background: 'rgba(192,57,43,0.3)', border: '1px solid rgba(220,38,38,0.35)' }}>
              ⚠️ {error}
            </div>
          )}

          <button type="submit" disabled={loading}
            className="w-full py-4 rounded-2xl text-sm font-black text-white disabled:opacity-60"
            style={{
              background: 'linear-gradient(135deg,#1a2fa8,#2952e3)',
              boxShadow: '0 6px 24px rgba(41,82,227,0.5)',
              letterSpacing: '0.08em',
            }}>
            {loading ? 'Signing in…' : 'SIGN IN'}
          </button>
        </form>

        <p className="text-center text-[10px] font-black uppercase tracking-[0.2em] mt-6"
          style={{ color: 'rgba(255,255,255,0.3)' }}>
          Prosperity · Integrity · Captivating
        </p>
      </div>

      <style>{'input::placeholder { color: rgba(255,255,255,0.35) !important; }'}</style>
    </div>
  );
};

// ── Role → Portal mapping ──────────────────────────────────────
const ROLE_PORTAL: Record<string, string> = {
  'Director':          'director',
  'VP':                'vp',
  'Principal':         'admin',
  'Coordinator':       'coordinator',
  'Accountant':        'accountant',
  'Admission Officer': 'admin',
  'Teacher':           'admin',
  'Examiner':          'examiner',
  'Academics':         'academics',
  'Receptionist':      'admin',
  'Registrar':         'admin',
};

// ── Root App ───────────────────────────────────────────────────
export default function App() {
  const [user,       setUser]       = useState<any>(null);
  const [userType,   setUserType]   = useState<'admin'|'student'|'teacher'|null>(null);
  const [portalType, setPortalType] = useState<string|null>(null);

  // Restore session from localStorage
  useEffect(() => {
    try {
      const saved = localStorage.getItem('pic_session');
      if (saved) {
        const parsed = JSON.parse(saved);
        setUser(parsed.user);
        setUserType(parsed.userType);
        setPortalType(parsed.portalType);
      }
    } catch {}
  }, []);

  const handleLogin = (loginUser: any, loginType: 'admin'|'student'|'teacher') => {
    let portal = 'admin';
    if (loginType === 'student') {
      portal = 'student';
    } else if (loginType === 'teacher') {
      portal = 'teacher';
    } else {
      portal = ROLE_PORTAL[loginUser.role] || 'admin';
    }
    setUser(loginUser);
    setUserType(loginType);
    setPortalType(portal);
    try {
      localStorage.setItem('pic_session', JSON.stringify({
        user: loginUser, userType: loginType, portalType: portal
      }));
    } catch {}
  };

  const handleLogout = () => {
    setUser(null); setUserType(null); setPortalType(null);
    try { localStorage.removeItem('pic_session'); } catch {}
  };

  if (!user || !portalType) {
    return <LoginScreen onLogin={handleLogin}/>;
  }

  // ── Route to correct portal ──────────────────────────────────

  if (portalType === 'teacher') {
    return (
      <TeacherPortal
        onLogout={handleLogout}
        teacherData={user}
        assignedStudents={[]}
      />
    );
  }

  if (portalType === 'student') {
    return (
      <StudentPortal
        onLogout={handleLogout}
        studentData={{
          roll_no:       user.roll_no,
          full_name:     user.full_name,
          class_section: user.class_section,
          username:      user.username,
        }}
      />
    );
  }

  if (portalType === 'vp') {
    return (
      <VPPortal
        onLogout={handleLogout}
        adminData={{ id: user.id, full_name: user.full_name, role: user.role, username: user.username }}
      />
    );
  }

  if (portalType === 'coordinator') {
    return (
      <CoordinatorPortal
        onLogout={handleLogout}
        adminData={{ id: user.id, full_name: user.full_name, role: user.role, username: user.username }}
      />
    );
  }

  if (portalType === 'examiner') {
    return (
      <ExaminerPortal
        onLogout={handleLogout}
        adminData={{ id: user.id, full_name: user.full_name, role: user.role, username: user.username }}
      />
    );
  }

  if (portalType === 'academics') {
    return (
      <AcademicsPortal
        onLogout={handleLogout}
        adminData={{ id: user.id, full_name: user.full_name, role: user.role, username: user.username }}
      />
    );
  }

  if (portalType === 'accountant') {
    return (
      <AccountantPortal
        onLogout={handleLogout}
        adminData={{ id: user.id, full_name: user.full_name, role: user.role, username: user.username }}
      />
    );
  }

  // Director, Principal, Accountant, Admission Officer,
  // Registrar, Receptionist → AdminPortal
  return (
    <AdminPortal
      onLogout={handleLogout}
      adminData={{ id: user.id, full_name: user.full_name, role: user.role, username: user.username }}
    />
  );
}